/*
 * A044516  Numbers n such that string 5,3 occurs in the base 6 representation
 *          of n but not of n+1.
 * https://oeis.org/A044516
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   Numbers n such that string 5,3 occurs in the base‑6
 *            representation of n but not of n+1. The sequence is generated by
 *            a simple linear scan
 * Range:     u8 n <= 8, u16 n <= 43, u32 n <= 43, u64 n <= 43, u128 n <= 43,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdbool.h>

static bool contains53(seq_t x)
{
    if (x < 6) return false;          /* less than two digits */
    uint8_t last = 0;                  /* previous less significant digit */
    while (x > 0) {
        uint8_t d = (uint8_t)(x % 6);  /* lowest digit */
        if (last == 3 && d == 5)      /* we found the substring 53 */
            return true;
        last = d;
        x = x / 6;
    }
    return false;
}

seq_t a(idx_t n)
{
    /* static cache of already computed terms */
    static seq_t *cache = NULL;
    static size_t cache_len = 0, cache_cap = 0;
    static seq_t next_candidate = 1; // first integer to test

    /* initialise cache the first time */
    if (cache == NULL) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }

    /* generate terms until we have the nth one */
    while (cache_len < n) {
        /* find the next number that satisfies the condition */
        for (;;) {
            if (contains53(next_candidate) && !contains53(next_candidate + 1)) {
                /* store it */
                if (cache_len >= cache_cap) {
                    cache_cap *= 2;
                    cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                }
                cache[cache_len++] = next_candidate;
                next_candidate++;
                break;
            }
            next_candidate++;
        }
    }

    /* return the cached term (zero‑based indexing) */
    return cache[n - 1];
}
